use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::os::unix::fs::MetadataExt;
use std::collections::HashMap;
use sha2::{Sha256, Digest};

const SESSION_DIR: &str = "/var/lib/app/sessions";
const MAX_SESSION_SIZE: u64 = 8192;

pub struct SessionManager {
    base_dir: PathBuf,
    expected_uid: u32,
}

impl SessionManager {
    pub fn new(base_dir: &str, uid: u32) -> Self {
        SessionManager {
            base_dir: PathBuf::from(base_dir),
            expected_uid: uid,
        }
    }

    /// Validates that a session ID contains only safe characters
    fn validate_session_id(session_id: &str) -> Result<(), &'static str> {
        if session_id.len() < 16 || session_id.len() > 64 {
            return Err("Invalid session ID length");
        }
        if !session_id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
            return Err("Invalid session ID characters");
        }
        Ok(())
    }

    /// Constructs the canonical path for a session file
    fn session_path(&self, session_id: &str) -> Result<PathBuf, &'static str> {
        let path = self.base_dir.join(session_id);
        // Ensure no path traversal
        let canonical_base = self.base_dir.canonicalize()
            .map_err(|_| "Cannot resolve base directory")?;
        // We check the parent exists and is our base
        let parent = path.parent().ok_or("Invalid path")?;
        let canonical_parent = parent.canonicalize()
            .map_err(|_| "Cannot resolve parent directory")?;
        if canonical_parent != canonical_base {
            return Err("Path traversal detected");
        }
        Ok(path)
    }

    /// Verifies file ownership and permissions before reading
    fn verify_file_security(&self, path: &Path) -> Result<(), &'static str> {
        let metadata = fs::symlink_metadata(path)
            .map_err(|_| "Cannot stat session file")?;

        // Reject symlinks
        if metadata.file_type().is_symlink() {
            return Err("Symlink detected - rejecting");
        }

        // Verify ownership
        if metadata.uid() != self.expected_uid {
            return Err("Session file ownership mismatch");
        }

        // Verify it's a regular file
        if !metadata.is_file() {
            return Err("Not a regular file");
        }

        // Check size limit
        if metadata.len() > MAX_SESSION_SIZE {
            return Err("Session file too large");
        }

        Ok(())
    }

    /// Loads session data from disk after security verification
    pub fn load_session(&self, session_id: &str) -> Result<HashMap<String, String>, &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;

        // Step 1: Verify file security properties
        self.verify_file_security(&path)?;

        // Step 2: Read the verified file
        let mut contents = String::new();
        let mut file = fs::File::open(&path)
            .map_err(|_| "Cannot open session file")?;
        file.read_to_string(&mut contents)
            .map_err(|_| "Cannot read session file")?;

        // Parse session data (simple key=value format)
        let mut session_data = HashMap::new();
        for line in contents.lines() {
            if let Some((key, value)) = line.split_once('=') {
                let key = key.trim().to_string();
                let value = value.trim().to_string();
                if key.len() <= 128 && value.len() <= 1024 {
                    session_data.insert(key, value);
                }
            }
        }

        Ok(session_data)
    }

    /// Saves session data to disk securely
    pub fn save_session(&self, session_id: &str, data: &HashMap<String, String>) -> Result<(), &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;

        let mut content = String::new();
        for (key, value) in data {
            if key.contains('=') || key.contains('\n') || value.contains('\n') {
                return Err("Invalid characters in session data");
            }
            content.push_str(&format!("{}={}\n", key, value));
        }

        if content.len() > MAX_SESSION_SIZE as usize {
            return Err("Session data too large");
        }

        fs::write(&path, content.as_bytes())
            .map_err(|_| "Cannot write session file")?;

        Ok(())
    }

    /// Deletes a session
    pub fn delete_session(&self, session_id: &str) -> Result<(), &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;
        self.verify_file_security(&path)?;
        fs::remove_file(&path).map_err(|_| "Cannot delete session")?;
        Ok(())
    }

    /// Generates a hash of session content for integrity checking
    pub fn session_fingerprint(&self, session_id: &str) -> Result<String, &'static str> {
        Self::validate_session_id(session_id)?;
        let path = self.session_path(session_id)?;
        self.verify_file_security(&path)?;

        let contents = fs::read(&path)
            .map_err(|_| "Cannot read session for fingerprint")?;

        let mut hasher = Sha256::new();
        hasher.update(&contents);
        Ok(format!("{:x}", hasher.finalize()))
    }
}

/// HTTP handler that processes session-based requests
pub fn handle_request(uid: u32, session_id: &str, action: &str) -> Result<String, &'static str> {
    let manager = SessionManager::new(SESSION_DIR, uid);

    match action {
        "load" => {
            let data = manager.load_session(session_id)?;
            Ok(format!("Session loaded with {} entries", data.len()))
        }
        "fingerprint" => {
            let fp = manager.session_fingerprint(session_id)?;
            Ok(format!("Fingerprint: {}", fp))
        }
        "delete" => {
            manager.delete_session(session_id)?;
            Ok("Session deleted".to_string())
        }
        _ => Err("Unknown action")
    }
}
